"""Local target parsing (no network)."""
import json

import pytest

import gws_drive as D
from gws_http import GwsError


def test_parse_stub_file(tmp_path):
    stub = tmp_path / "Budget.gsheet"
    stub.write_text(json.dumps({
        "": "WARNING! DO NOT EDIT THIS FILE!", "doc_id": "ABC123doc_id_long_enough",
        "resource_key": "", "email": "user@example.com"}))
    r = D.parse_target(str(stub))
    assert r["id"] == "ABC123doc_id_long_enough"
    assert r["hint_type"] == "sheet"
    assert r["local_path"] == str(stub)
    assert r["stub_email"] == "user@example.com"


def test_parse_stub_with_resource_key(tmp_path):
    stub = tmp_path / "x.gdoc"
    stub.write_text(json.dumps({"doc_id": "id_2222222222222222", "resource_key": "RK7"}))
    r = D.parse_target(str(stub))
    assert r["id"] == "id_2222222222222222"
    assert r["resource_key"] == "RK7"
    assert r["hint_type"] == "doc"


def test_parse_urls():
    doc = D.parse_target("https://docs.google.com/document/d/DOCID_1234567890123/edit")
    assert doc["id"] == "DOCID_1234567890123" and doc["hint_type"] == "doc"
    sheet = D.parse_target("https://docs.google.com/spreadsheets/d/SHEETID_123456789/edit#gid=0")
    assert sheet["id"] == "SHEETID_123456789" and sheet["hint_type"] == "sheet"


def test_parse_url_resourcekey_query():
    r = D.parse_target("https://docs.google.com/document/d/DID_123456789012345?resourcekey=RK9")
    assert r["id"] == "DID_123456789012345"
    assert r["resource_key"] == "RK9"


def test_parse_url_tab_id():
    r = D.parse_target("https://docs.google.com/document/d/DID_123456789012345/edit?tab=t.9v1vzzunyaxm")
    assert r["id"] == "DID_123456789012345"
    assert r["tab_id"] == "t.9v1vzzunyaxm"


def test_parse_bare_id():
    r = D.parse_target("1a2b3c4d5e6f7g8h9i0jKLMNOP")
    assert r["id"] == "1a2b3c4d5e6f7g8h9i0jKLMNOP"
    assert r["hint_type"] is None


def test_parse_shortcut_target_path():
    p = "/x/.shortcut-targets-by-id/TARGETID_987654321/Some Folder/thing"
    r = D.parse_target(p)
    assert r["id"] == "TARGETID_987654321"


def test_bad_target_raises():
    with pytest.raises(GwsError):
        D.parse_target("not a url or id !!")


# --- sensitivity via Drive parent-walk (no network; fake drive) ----------------------------
class _FakeDrive:
    """Minimal Drive stub: files().get(fileId=...).execute() looks up a table of {id: meta}."""
    def __init__(self, table):
        self.table = table

    def files(self):
        drive = self

        class _Files:
            def get(self, fileId, **kwargs):
                data = drive.table[fileId]

                class _Req:
                    def execute(self_inner):
                        return data
                return _Req()
        return _Files()


def test_ancestor_folder_names_walks_up():
    table = {"p1": {"id": "p1", "name": "finances", "parents": ["root"]},
             "root": {"id": "root", "name": "My Drive"}}
    assert D.ancestor_folder_names(_FakeDrive(table), ["p1"]) == ["finances", "My Drive"]


def test_sensitivity_true_when_ancestor_is_sensitive():
    table = {"p1": {"id": "p1", "name": "finances", "parents": ["root"]},
             "root": {"id": "root", "name": "My Drive"}}
    v = D._sensitivity(_FakeDrive(table), ["p1"], None)
    assert v["sensitive"] is True and v["sensitivity_unverified"] is False


def test_sensitivity_false_for_ordinary_folder():
    table = {"p2": {"id": "p2", "name": "trips", "parents": []}}
    v = D._sensitivity(_FakeDrive(table), ["p2"], None)
    assert v["sensitive"] is False


def test_sensitivity_from_local_path_even_if_parents_unknown():
    v = D._sensitivity(_FakeDrive({}), None, "/x/My Drive/finances/a.gsheet")
    assert v["sensitive"] is True


def test_sensitivity_unverified_when_nothing_to_go_on():
    v = D._sensitivity(_FakeDrive({}), None, None)
    assert v["sensitive"] is False and v["sensitivity_unverified"] is True
